INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B001', 'HDSAT-RW-M35-B001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'As of June 2025_______ the Seed Vault conserves 1,355,591 accessions, representing more than 13,000 years of agricultural history.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": "; "}, {"id": "C", "text": ", "}, {"id": "D", "text": " and "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Svalbard Global Seed Vault", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Svalbard_Global_Seed_Vault', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B001', 'C', ARRAY['C']::TEXT[], 'The time phrase ''As of June 2025'' is an introductory element, so a comma separates it from the main clause that follows. A semicolon or colon would need a complete clause before it, and ''and'' would fuse the date into the subject.', '{"B": "A semicolon cannot follow a time phrase that has no verb.", "A": "A colon must follow an independent clause.", "D": "''and'' would join the date to the subject ungrammatically."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B002', 'HDSAT-RW-M35-B002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In one study_______ Simard watched as a Douglas fir that had been injured by insects appeared to send chemical warning signals to a ponderosa pine growing nearby.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": "; "}, {"id": "C", "text": " and "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycorrhizal network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycorrhizal_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B002', 'D', ARRAY['D']::TEXT[], 'The prepositional phrase ''In one study'' introduces the sentence but is not a clause, so only a comma can set it off from the main clause. The other marks either require an independent clause or break the phrase''s connection to the subject.', '{"B": "A semicolon needs an independent clause before it.", "A": "A colon cannot introduce the subject of its own sentence.", "C": "''and'' would make the phrase part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B003', 'HDSAT-RW-M35-B003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'Although neither Voyager spacecraft is heading toward any particular star_______ Voyager 1 will pass within 1.6 light-years'' distance of the star Gliese 445, currently in the constellation Camelopardalis, in about 40,000 years.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": ", "}, {"id": "C", "text": ": "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Voyager Golden Record", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Voyager_Golden_Record', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B003', 'B', ARRAY['B']::TEXT[], 'The ''Although'' clause is subordinate, so it is attached to the main clause by a comma. A semicolon or colon would wrongly treat the dependent clause as an independent one, and ''and'' would remove the concession the sentence depends on.', '{"D": "A semicolon must join two independent clauses.", "C": "A colon would falsely present the concession as complete.", "A": "''and'' would turn the concession into an addition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B004', 'HDSAT-RW-M35-B004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'On 26 April 1986_______ reactor 4 of the Chernobyl Nuclear Power Plant, located near Pripyat in the Ukrainian SSR of the Soviet Union, exploded.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": " and "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Chernobyl disaster", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Chernobyl_disaster', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B004', 'A', ARRAY['A']::TEXT[], 'A date phrase at the start of a sentence is introductory and takes a comma before the main clause. A semicolon or colon requires a clause on its left, and ''and'' would attach the date to the subject instead of setting it off.', '{"B": "A semicolon cannot follow a bare date phrase.", "D": "A colon needs a complete clause before it.", "C": "''and'' would make the date part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B005', 'HDSAT-RW-M35-B005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In residential design_______ open plan or open concept (the term used mainly in Canada) describes the elimination of barriers such as walls and doors that traditionally separated distinct functional areas, such as combining the kitchen, living room, and dining room into a single great room.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": " and "}, {"id": "C", "text": "; "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Open plan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Open_plan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B005', 'A', ARRAY['A']::TEXT[], 'The opening prepositional phrase names the field being discussed, and a comma marks its boundary with the subject ''open plan or open concept''. The semicolon, colon and ''and'' all misrepresent the phrase as a clause or as part of the subject.', '{"C": "The phrase has no verb, so a semicolon is impossible.", "D": "A colon must follow an independent clause.", "B": "''and'' would merge the field with the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B006', 'HDSAT-RW-M35-B006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'Since the late 20th century_______ technological advances in lithium batteries—which offer superior energy density and current output versus lead-acid batteries—have revived public interest as zero-emission vehicle options.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": ": "}, {"id": "D", "text": " and "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Electric vehicle", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Electric_vehicle', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B006', 'A', ARRAY['A']::TEXT[], 'The ''Since'' phrase is a time expression, not a clause, so a comma separates it from the main clause ''technological advances ... have revived''. The other choices either require an independent clause or fuse the time phrase into the subject.', '{"B": "A semicolon must follow an independent clause.", "C": "A colon needs a clause before it.", "D": "''and'' would join the time phrase to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B007', 'HDSAT-RW-M35-B007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In the Information Age_______ people without access to the Internet and other technology are at a disadvantage, for they are less able to connect with others, find and apply for jobs, shop, and learn.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": ": "}, {"id": "C", "text": ", "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Digital divide", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Digital_divide', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B007', 'C', ARRAY['C']::TEXT[], 'The introductory phrase ''In the Information Age'' sets the time period and must be closed with a comma before the main clause. A semicolon or colon would need a full clause on the left, and ''and'' would attach the phrase to the subject.', '{"D": "The phrase is not an independent clause.", "B": "A colon cannot precede the subject this way.", "A": "''and'' would change the phrase into part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B008', 'HDSAT-RW-M35-B008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'While the observation of objects in space, known as astronomy, predates reliable recorded history_______ it was the development of large and relatively efficient rockets during the mid-twentieth century that allowed physical space exploration to become a reality.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": ", "}, {"id": "C", "text": "; "}, {"id": "D", "text": " and "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Space exploration", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Space_exploration', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B008', 'B', ARRAY['B']::TEXT[], 'The ''While'' clause is dependent, even though it is long and contains an appositive, so a comma joins it to the main clause. A semicolon would wrongly make it independent, a colon would announce an explanation, and ''and'' would distort the contrast.', '{"C": "A semicolon requires two independent clauses.", "A": "A colon would misread the clause as complete.", "D": "''and'' would erase the contrast the sentence sets up."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B009', 'HDSAT-RW-M35-B009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In the 1970s_______ focus shifted from one-off flights to renewable hardware, such as the Space Shuttle program, and from competition to cooperation, the foremost example being the International Space Station (ISS), built between 1998 and 2011.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": ": "}, {"id": "C", "text": " and "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Space exploration", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Space_exploration', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B009', 'A', ARRAY['A']::TEXT[], 'The decade phrase is introductory, so it is followed by a comma before ''focus shifted''. Only a comma can separate a non-clausal time phrase from the main clause; the other marks either need a clause or would merge the phrase with the subject.', '{"D": "A semicolon cannot follow a decade phrase alone.", "B": "A colon must be preceded by an independent clause.", "C": "''and'' would make the decade part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B010', 'HDSAT-RW-M35-B010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'Because minimum wages increase the cost of labor_______ companies often try to avoid minimum wage laws by using gig workers, by moving labor to locations with lower or nonexistent minimum wages, or by automating job functions.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": ": "}, {"id": "C", "text": " and "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Minimum wage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Minimum_wage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B010', 'D', ARRAY['D']::TEXT[], 'The ''Because'' clause gives the reason for the main clause and is subordinate, so a comma marks the boundary. A semicolon would treat the reason as an independent sentence, a colon would present it as an explanation of itself, and ''and'' would remove the causal link.', '{"A": "A semicolon must join independent clauses.", "B": "A colon cannot follow a dependent clause.", "C": "''and'' would replace the causal relation with addition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B011', 'HDSAT-RW-M35-B011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'As of 2026_______ no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": " and "}, {"id": "C", "text": ": "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Universal basic income", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Universal_basic_income', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B011', 'D', ARRAY['D']::TEXT[], 'The date phrase introduces the claim that follows, so a comma separates it from the main clause. The semicolon and colon both demand a complete clause before them, and ''and'' would attach the date to the subject.', '{"A": "A semicolon needs an independent clause on its left.", "C": "A colon cannot follow a bare date phrase.", "B": "''and'' would fuse the date into the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B012', 'HDSAT-RW-M35-B012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'While systems such as buses and railways are commonly cited_______ air travel is often excluded from general discussions of public transport due to its market-driven structure and competitive pricing.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": " and "}, {"id": "C", "text": ", "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Public transport", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Public_transport', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B012', 'C', ARRAY['C']::TEXT[], 'The ''While'' clause is a dependent concession, so it is joined to the main clause by a comma. A semicolon or colon would treat the concession as a complete sentence, and ''and'' would turn the contrast into a simple addition.', '{"D": "A semicolon must separate independent clauses.", "A": "A colon would falsely present the concession as complete.", "B": "''and'' would remove the contrast."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B013', 'HDSAT-RW-M35-B013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'By setting a price on an over-consumed product_______ congestion pricing encourages the redistribution of the demand in space or in time, leading to more efficient outcomes.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": ": "}, {"id": "C", "text": ", "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Congestion pricing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Congestion_pricing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B013', 'C', ARRAY['C']::TEXT[], 'The ''By'' phrase describes the means by which congestion pricing works, and a comma sets it off from the main clause. A semicolon or colon requires an independent clause before it, and ''and'' would make the means part of the subject.', '{"D": "The ''By'' phrase is not a clause.", "B": "A colon cannot follow this participial phrase.", "A": "''and'' would join the means to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B014', 'HDSAT-RW-M35-B014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In a placebo-controlled trial_______ any change in the control group is known as the placebo response, and the difference between this and the result of no treatment is the placebo effect.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": " and "}, {"id": "C", "text": ", "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Placebo", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Placebo', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B014', 'C', ARRAY['C']::TEXT[], 'The opening phrase names the setting of the trial and is followed by a comma before the main clause. A semicolon or colon would need a clause on its left, and ''and'' would make the setting part of the subject.', '{"D": "The setting phrase has no verb.", "A": "A colon must follow an independent clause.", "B": "''and'' would attach the setting to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
