INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B015', 'C', ARRAY['C']::TEXT[], 'The time phrase is introductory and must be separated from the main clause by a comma. The semicolon and colon require a complete clause before them, and ''and'' would make the time phrase part of the subject.', '{"A": "A semicolon cannot follow a bare time phrase.", "D": "A colon needs an independent clause before it.", "B": "''and'' would fuse the time phrase into the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B016', 'HDSAT-RW-M35-B016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'During the multinational occupation of post–World War II Germany_______ the Soviet Union blocked the Western Allies'' railway, road, and canal access to the sectors of Berlin under Western control.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": "; "}, {"id": "C", "text": " and "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Berlin Blockade", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Berlin_Blockade', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B016', 'D', ARRAY['D']::TEXT[], 'The ''During'' phrase is an introductory modifier, so a comma separates it from the main clause about the Soviet Union. A semicolon or colon would require a clause before it, and ''and'' would make the occupation part of the subject.', '{"B": "The ''During'' phrase is not a clause.", "A": "A colon must follow a complete clause.", "C": "''and'' would join the modifier to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B017', 'HDSAT-RW-M35-B017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'After John''s death_______ the regency government of his young son, Henry III, reissued the document in 1216, stripped of some of its more radical content, in an unsuccessful bid to build political support for their cause.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": ": "}, {"id": "C", "text": " and "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Magna Carta", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Magna_Carta', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B017', 'D', ARRAY['D']::TEXT[], 'The phrase ''After John''s death'' is a time expression, not a clause, and a comma sets it off from the main clause. The semicolon and colon both need an independent clause before them, while ''and'' would attach the time phrase to the subject.', '{"A": "A semicolon cannot follow a prepositional phrase.", "B": "A colon needs a clause on its left.", "C": "''and'' would make the time phrase part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B018', 'HDSAT-RW-M35-B018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In the detailed Japanese classification_______ origami is divided into stylized ceremonial origami (儀礼折り紙, girei origami) and recreational origami (遊戯折り紙, yūgi origami), and only recreational origami is generally recognized as origami.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": " and "}, {"id": "C", "text": "; "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Origami", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Origami', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B018', 'D', ARRAY['D']::TEXT[], 'The introductory phrase locates the classification being described, so a comma marks its boundary with the main clause. A semicolon or colon would require a full clause before the mark, and ''and'' would merge the phrase into the subject.', '{"C": "The phrase is not an independent clause.", "A": "A colon cannot follow this prepositional phrase.", "B": "''and'' would attach the phrase to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B019', 'HDSAT-RW-M35-B019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'As jazz spread around the world_______ it drew on national, regional, and local musical cultures, which gave rise to different styles.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": ", "}, {"id": "C", "text": ": "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Jazz", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Jazz', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B019', 'B', ARRAY['B']::TEXT[], 'The ''As'' clause describes the circumstances in which jazz changed and is subordinate, so a comma joins it to the main clause. A semicolon would make it independent, a colon would present it as an announcement, and ''and'' would remove the connection.', '{"D": "A semicolon must join two independent clauses.", "C": "A colon cannot follow a dependent clause.", "A": "''and'' would turn the circumstance into an addition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
