INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B020', 'B', ARRAY['B']::TEXT[], 'The decade phrase introduces the list of styles that follows and takes a comma before the subject. The semicolon and colon require a complete clause on their left, and ''and'' would attach the decade to the subject.', '{"A": "A semicolon cannot follow a decade phrase.", "D": "A colon needs a clause before it.", "C": "''and'' would make the decade part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B021', 'HDSAT-RW-M35-B021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In Japanese_______ haiku are traditionally printed as a single line, while haiku in English often appear as three lines, although variations exist.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": "; "}, {"id": "C", "text": ": "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Haiku", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Haiku', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B021', 'D', ARRAY['D']::TEXT[], 'The language phrase ''In Japanese'' is introductory, so a comma separates it from the main clause. The semicolon and colon would need an independent clause before them, and ''and'' would incorrectly join the language to the subject.', '{"B": "The language phrase has no verb.", "C": "A colon must follow a complete clause.", "A": "''and'' would fuse the phrase into the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B022', 'HDSAT-RW-M35-B022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'When the British defeated the French_______ they took the stone to London under the terms of the Capitulation of Alexandria in 1801.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ": "}, {"id": "B", "text": " and "}, {"id": "C", "text": "; "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Rosetta Stone", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Rosetta_Stone', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B022', 'D', ARRAY['D']::TEXT[], 'The ''When'' clause is a dependent time clause, so a comma separates it from the main clause. A semicolon would incorrectly make it independent, a colon would announce an explanation, and ''and'' would make the two events merely additive.', '{"C": "A semicolon requires an independent clause before it.", "A": "A colon cannot follow this dependent clause.", "B": "''and'' would remove the time relation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B023', 'HDSAT-RW-M35-B023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'Before entering hibernation_______ animals need to store enough energy to last through the duration of their dormant period, possibly as long as an entire winter.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": ": "}, {"id": "D", "text": " and "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Hibernation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Hibernation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B023', 'A', ARRAY['A']::TEXT[], 'The ''Before'' phrase is an introductory time expression and is followed by a comma before the main clause. A semicolon or colon would need a clause on the left, and ''and'' would attach the time phrase to the subject.', '{"B": "The ''Before'' phrase is not a clause.", "C": "A colon needs a complete clause before it.", "D": "''and'' would make the phrase part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B024', 'HDSAT-RW-M35-B024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In a mycorrhizal association_______ the fungus colonizes the host plant''s root tissues, either intracellularly as in arbuscular mycorrhizal fungi, or extracellularly as in ectomycorrhizal fungi.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": ": "}, {"id": "C", "text": ", "}, {"id": "D", "text": " and "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Mycorrhiza", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Mycorrhiza', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B024', 'C', ARRAY['C']::TEXT[], 'The opening phrase names the relationship being described, and a comma sets it off from the main clause. A semicolon or colon would require a complete clause before it, and ''and'' would attach the phrase to the subject.', '{"A": "The phrase has no finite verb.", "B": "A colon must follow an independent clause.", "D": "''and'' would merge the phrase into the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B025', 'HDSAT-RW-M35-B025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'As of 2024_______ hundreds of thousands of large turbines, in installations known as wind farms, were generating over 1,136 gigawatts of power, with 117 GW added each year.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": ": "}, {"id": "C", "text": "; "}, {"id": "D", "text": " and "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Wind turbine", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Wind_turbine', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B025', 'A', ARRAY['A']::TEXT[], 'The date phrase is introductory and takes a comma before the main clause. The semicolon and colon both need an independent clause on their left, and ''and'' would make the date part of the subject.', '{"C": "A semicolon cannot follow a bare date phrase.", "B": "A colon needs a clause before it.", "D": "''and'' would fuse the date into the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B026', 'HDSAT-RW-M35-B026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'In the three decades since Li-ion batteries were first sold in 1991_______ their volumetric energy density increased threefold while their cost dropped tenfold.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": " and "}, {"id": "C", "text": ", "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Lithium-ion battery", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Lithium-ion_battery', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B026', 'C', ARRAY['C']::TEXT[], 'The long time phrase introduces the period being measured and is closed with a comma before the main clause. A semicolon or colon would need a full clause before it, and ''and'' would make the period part of the subject.', '{"A": "The time phrase is not an independent clause.", "D": "A colon cannot follow this phrase.", "B": "''and'' would join the period to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B027', 'HDSAT-RW-M35-B027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In late 2024_______ global demand passed 1 terawatt-hour per year, while production capacity was more than twice that.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": ": "}, {"id": "C", "text": "; "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Lithium-ion battery", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Lithium-ion_battery', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B027', 'D', ARRAY['D']::TEXT[], 'The opening date phrase is introductory and must be followed by a comma before the main clause. A semicolon or colon requires an independent clause before it, and ''and'' would attach the date to the subject.', '{"C": "A semicolon cannot follow a date phrase alone.", "B": "A colon must be preceded by a clause.", "A": "''and'' would make the date part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B028', 'HDSAT-RW-M35-B028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'As stress on the need for freshwater intensifies globally_______ desalination has become a key part of strategies for global water security.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": ": "}, {"id": "C", "text": "; "}, {"id": "D", "text": ", "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desalination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desalination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B028', 'D', ARRAY['D']::TEXT[], 'The ''As'' clause sets the condition for the main clause and is dependent, so a comma joins the two. A semicolon would make the condition independent, a colon would announce it as an explanation, and ''and'' would weaken the causal connection.', '{"C": "A semicolon must join independent clauses.", "B": "A colon cannot follow a dependent clause.", "A": "''and'' would turn the condition into a simple addition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B029', 'HDSAT-RW-M35-B029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'As of 2023_______ the largest form of grid storage is pumped-storage hydroelectricity, with utility-scale batteries and behind-the-meter batteries coming second and third.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": ": "}, {"id": "C", "text": " and "}, {"id": "D", "text": "; "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Grid energy storage", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Grid_energy_storage', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B029', 'A', ARRAY['A']::TEXT[], 'The date phrase introduces the ranking that follows, so a comma separates it from the main clause. A semicolon or colon would need a clause before the mark, and ''and'' would fuse the date into the subject.', '{"D": "A semicolon needs an independent clause before it.", "B": "A colon cannot follow a bare date phrase.", "C": "''and'' would attach the date to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
