INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B030', 'C', ARRAY['C']::TEXT[], 'The ''While'' clause concedes that definitions differ and is dependent, so a comma joins it to the main clause. A semicolon would make it independent, a colon would present it as an explanation, and ''and'' would remove the concession.', '{"B": "A semicolon must separate independent clauses.", "D": "A colon cannot follow a dependent clause.", "A": "''and'' would erase the concession."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B031', 'HDSAT-RW-M35-B031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'In the mid-20th century_______ urban planning experts such as Jane Jacobs called on urban planners to take resident experiences and needs more into consideration.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": " and "}, {"id": "B", "text": "; "}, {"id": "C", "text": ", "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban planning", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_planning', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B031', 'C', ARRAY['C']::TEXT[], 'The time phrase is introductory and takes a comma before the main clause. The semicolon and colon require a complete clause before them, and ''and'' would make the time phrase part of the subject.', '{"B": "A semicolon cannot follow a bare time phrase.", "D": "A colon needs a clause on its left.", "A": "''and'' would attach the date to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B032', 'HDSAT-RW-M35-B032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'During this period_______ Rome''s control expanded from the city''s immediate surroundings to hegemony over the entire Mediterranean world.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "; "}, {"id": "B", "text": " and "}, {"id": "C", "text": ", "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Roman Republic", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Roman_Republic', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B032', 'C', ARRAY['C']::TEXT[], 'The prepositional phrase ''During this period'' is introductory and is set off by a comma before the main clause. A semicolon or colon would require an independent clause before it, and ''and'' would merge the phrase into the subject.', '{"A": "The phrase is not an independent clause.", "D": "A colon must follow a complete clause.", "B": "''and'' would make the phrase part of the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B033', 'HDSAT-RW-M35-B033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'At its zenith, perhaps in the first half of the first millennium (1 CE to 500 CE)_______ Teotihuacan was the largest city in the Americas.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": " and "}, {"id": "C", "text": "; "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Teotihuacan", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Teotihuacan', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B033', 'A', ARRAY['A']::TEXT[], 'The opening phrase locates the city at its height and includes a parenthetical date range, but it remains introductory, so a comma precedes the main clause. The other marks either require a clause or would fuse the phrase into the subject.', '{"C": "The phrase is not a clause, despite its length.", "D": "A colon cannot follow this modifier.", "B": "''and'' would attach the phrase to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B034', 'HDSAT-RW-M35-B034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'In return for $15 million_______ or approximately $18 per square mile ($7/km2), the United States nominally acquired a total of 828,000 sq mi (2,140,000 km2; 530,000,000 acres) of land now in the Central United States.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": " and "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Louisiana Purchase", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Louisiana_Purchase', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B034', 'A', ARRAY['A']::TEXT[], 'The ''In return for'' phrase states the price and is introductory, so it is separated from the main clause by a comma. A semicolon or colon would need a clause before it, and ''and'' would make the price part of the subject.', '{"B": "The price phrase is not a clause.", "D": "A colon needs an independent clause before it.", "C": "''and'' would attach the price to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M35-B035', 'HDSAT-RW-M35-B035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Hard', 'multiple_choice', 'Although peace terms were agreed upon in the December 1814 Treaty of Ghent_______ the war did not officially end until the peace treaty was ratified by the United States Senate on 17 February 1815.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", "}, {"id": "B", "text": "; "}, {"id": "C", "text": " and "}, {"id": "D", "text": ": "}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "War of 1812", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/War_of_1812', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B035', 'A', ARRAY['A']::TEXT[], 'The ''Although'' clause is a dependent concession, so it is attached to the main clause with a comma. A semicolon would treat it as independent, a colon would present it as a complete explanation, and ''and'' would remove the contrast.', '{"B": "A semicolon must join two independent clauses.", "D": "A colon cannot follow a dependent clause.", "C": "''and'' would replace the concession with addition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
