INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B037', 'D', ARRAY['D']::TEXT[], 'The date phrase is introductory and takes a comma before the main clause. A semicolon or colon would need a clause on its left, and ''and'' would make the date part of the subject.', '{"C": "A semicolon cannot follow a date phrase alone.", "B": "A colon needs an independent clause before it.", "A": "''and'' would attach the date to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
