INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M35-B040', 'C', ARRAY['C']::TEXT[], 'The field phrase ''In economics'' is introductory, so a comma separates it from the definition that follows. A semicolon or colon would require an independent clause before it, and ''and'' would fuse the field into the subject.', '{"B": "The field phrase is not a clause.", "A": "A colon cannot precede the subject this way.", "D": "''and'' would attach the field to the subject."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
